def sha256(data: bytes) -> str: return hashlib.sha256(data).hexdigest()
def main() -> None:
    parser=argparse.ArgumentParser(description=__doc__); parser.add_argument("source_root",type=pathlib.Path); args=parser.parse_args(); root=args.source_root.resolve()
    if not (root/"go.mod").is_file(): raise SystemExit(f"not a HYZoraX source root: {root}")
